namespace BookingMgmt.Application.MapFactories.MapDTOToDomain
{
    internal static class MappingToDomainFactory
    {
        internal static MappingBase GetFor(EnumDomain model)
        {
            switch (model)
            {
                case EnumDomain.Booking:
                    return new FromBookingDTO();
                case EnumDomain.Journey:
                    return new FromJourneyDTO();
                default:
                    throw new NotImplementedException($"The mapping for type {model} is not implemented.");
            }
        }
    }
}

namespace BookingMgmt.Application.MapFactories
{
    internal abstract class MappingBase
    {
        internal IEnumerable<TOutput> GetCollection<TInput, TOutput>(IEnumerable<TInput> source)
            where TInput : class
            where TOutput : class
        {
            if (source == null) { yield break; }

            foreach (var item in source)
            {
                yield return Get<TInput, TOutput>(item);
            }
        }

        internal abstract TOutput Get<TInput, TOutput>(TInput source) 
            where TInput : class
            where TOutput : class;
    }
}

